arguments.command:
cd /tmp && python3 -c "
import json
# test deep nesting behavior of json C scanner
for depth in (100, 900, 2000, 100000):
    s = '['*depth + ']'*depth
    try:
        r = json.loads(s)
        print(depth, 'ok', type(r))
    except RecursionError as e:
        print(depth, 'RecursionError')
    except ValueError as e:
        print(depth, 'ValueError', str(e)[:50])
"
